  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../prisma-client\" // Verifica si esta ruta es correcta para tu estructura de carpetas\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// 1. EL NEGOCIO (La entidad principal)\nmodel Business {\n  id        Int      @id @default(autoincrement())\n  name      String // Ej: \"CENTRAL\", \"Modas Juanita\"\n  createdAt DateTime @default(now())\n\n  // Un negocio tiene muchos usuarios, productos y ventas\n  users    User[]\n  products Product[]\n  sales    Sale[]\n}\n\n// --- MODELO DE USUARIO ---\nmodel User {\n  id           Int    @id @default(autoincrement())\n  email        String @unique\n  passwordHash String\n  fullName     String\n  role         String @default(\"OWNER\") // \"OWNER\" (Dueño) o \"SELLER\" (Vendedor)\n\n  // Relación: El usuario pertenece a un Negocio\n  businessId Int\n  business   Business @relation(fields: [businessId], references: [id])\n\n  // Un usuario realiza ventas (Auditoría: saber quién vendió)\n  sales           Sale[]\n  createdAt       DateTime  @default(now())\n  // RELACIONES DE AUDITORÍA (Nombres explícitos)\n  createdProducts Product[] @relation(\"CreatedBy\")\n  updatedProducts Product[] @relation(\"UpdatedBy\")\n  // Relaciones: Un usuario tiene muchos productos y muchas ventas\n}\n\n// --- MODELO DE CATEGORÍA ---\nmodel Category {\n  id      Int    @id @default(autoincrement())\n  name    String\n  iconKey String\n\n  // NUEVO CAMPO: Define qué escala usa (LETTER, NUMERIC, SHOES)\n  sizeType String @default(\"LETTER\")\n\n  products Product[]\n}\n\n// --- MODELO DE PRODUCTO (Maestro) ---\nmodel Product {\n  id        Int      @id @default(autoincrement())\n  name      String\n  price     Float // Precio base\n  color     String   @default(\"Blue\") // <--- NUEVO CAMPO\n  // 1. FECHAS AUTOMÁTICAS (Prisma se encarga solo)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt // <--- Se actualiza sola cada vez que tocas el registro\n\n  // 2. ¿QUIÉN LO CREÓ? (Obligatorio)\n  createdById Int\n  createdBy   User @relation(\"CreatedBy\", fields: [createdById], references: [id])\n\n  // 3. ¿QUIÉN LO MODIFICÓ? (Opcional, puede ser null al principio)\n  updatedById Int?\n  updatedBy   User?    @relation(\"UpdatedBy\", fields: [updatedById], references: [id])\n  // Relación: Producto pertenece al Negocio (NO al usuario específico)\n  businessId  Int\n  business    Business @relation(fields: [businessId], references: [id])\n\n  categoryId Int\n  category   Category @relation(fields: [categoryId], references: [id])\n\n  variations Variation[]\n}\n\n// --- MODELO DE VARIACIÓN (Tallas y Stock) ---\nmodel Variation {\n  id    Int    @id @default(autoincrement())\n  size  String // \"S\", \"M\", \"L\", \"XL\"\n  stock Int    @default(0)\n\n  // Relación con Producto\n  productId Int\n  product   Product @relation(fields: [productId], references: [id])\n\n  // Relación con los items vendidos\n  saleItems SaleItem[]\n}\n\n// --- MODELO DE VENTA (Cabecera) ---\nmodel Sale {\n  id    Int      @id @default(autoincrement())\n  total Float\n  date  DateTime @default(now())\n\n  businessId Int\n  business   Business @relation(fields: [businessId], references: [id])\n\n  // ¿Quién hizo la venta?\n  userId Int\n  user   User @relation(fields: [userId], references: [id])\n\n  items SaleItem[]\n}\n\n// --- MODELO DE DETALLE DE VENTA (Filas) ---\nmodel SaleItem {\n  id       Int   @id @default(autoincrement())\n  quantity Int\n  price    Float // Precio al momento de la venta\n\n  // Relación con la Venta Padre\n  saleId Int\n  sale   Sale @relation(fields: [saleId], references: [id])\n\n  // Relación con la Variación vendida (Talla específica)\n  variationId Int\n  variation   Variation @relation(fields: [variationId], references: [id])\n}\n",
